import React, { useEffect, useState } from "react";
import { getAnalytics } from "../../services/api";
import { DollarSign, ShoppingBag, Package, Users, Loader2, TrendingUp } from "lucide-react";
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
} from "recharts";

const STAT_CARDS = [
  { key: 'totalRevenue', label: 'Tổng Doanh Thu', Icon: DollarSign, color: 'blue', format: true },
  { key: 'totalOrders', label: 'Tổng Đơn Hàng', Icon: ShoppingBag, color: 'green', format: false },
  { key: 'totalProducts', label: 'Tổng Sản Phẩm', Icon: Package, color: 'orange', format: false },
  { key: 'totalUsers', label: 'Tổng Khách Hàng', Icon: Users, color: 'purple', format: false },
];

const COLOR_MAP = {
  blue:   { bg: 'bg-blue-50',   text: 'text-blue-600'   },
  green:  { bg: 'bg-green-50',  text: 'text-green-600'  },
  orange: { bg: 'bg-orange-50', text: 'text-orange-600' },
  purple: { bg: 'bg-purple-50', text: 'text-purple-600' },
};

export default function AdminDashboard() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    getAnalytics()
      .then((res) => setData(res.data))
      .catch((err) => console.error(err))
      .finally(() => setLoading(false));
  }, []);

  const formatVND = (n) =>
    new Intl.NumberFormat("vi-VN", { style: "currency", currency: "VND" }).format(n);

  if (loading) {
    return (
      <div className="p-8">
        {/* Header skeleton */}
        <div className="mb-8">
          <div className="h-8 w-56 bg-gray-200 rounded animate-pulse mb-2" />
          <div className="h-4 w-72 bg-gray-200 rounded animate-pulse" />
        </div>
        {/* Stat card skeletons */}
        <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-5 mb-8">
          {[1,2,3,4].map(i => (
            <div key={i} className="bg-white border border-gray-200 rounded-2xl p-5 animate-pulse">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-gray-200 rounded-xl" />
                <div className="flex-1">
                  <div className="h-3 w-24 bg-gray-200 rounded mb-2" />
                  <div className="h-7 w-20 bg-gray-200 rounded" />
                </div>
              </div>
            </div>
          ))}
        </div>
        {/* Chart skeleton */}
        <div className="bg-white border border-gray-200 rounded-2xl p-6 animate-pulse">
          <div className="h-5 w-48 bg-gray-200 rounded mb-6" />
          <div className="h-80 bg-gray-100 rounded-xl" />
        </div>
      </div>
    );
  }

  if (!data) return (
    <div className="flex items-center justify-center h-64 text-gray-400">
      <p>Không thể tải dữ liệu thống kê</p>
    </div>
  );

  return (
    <div className="p-8">
      {/* Page header */}
      <div className="mb-8">
        <div className="flex items-center gap-2 text-[0.62rem] font-bold tracking-[0.28em] uppercase text-yellow-700 mb-2">
          <TrendingUp size={12} /> Quản trị
        </div>
        <h1 className="text-3xl font-normal text-gray-900 font-serif">Tổng quan hệ thống</h1>
      </div>

      {/* Stat cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-5 mb-8">
        {STAT_CARDS.map(({ key, label, Icon, color, format }) => {
          const { bg, text } = COLOR_MAP[color];
          return (
            <div key={key} className="bg-white border border-gray-200 rounded-2xl p-5 shadow-sm hover:shadow-md transition-shadow">
              <div className="flex items-center gap-4">
                <div className={`w-12 h-12 ${bg} rounded-xl flex items-center justify-center shrink-0`}>
                  <Icon size={22} className={text} />
                </div>
                <div>
                  <p className="text-xs text-gray-500 mb-0.5">{label}</p>
                  <h3 className="text-xl font-bold text-gray-900">
                    {format ? formatVND(data[key]) : data[key]?.toLocaleString()}
                  </h3>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {/* Revenue chart */}
      <div className="bg-white border border-gray-200 rounded-2xl p-6 shadow-sm">
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-lg font-semibold text-gray-900">Biểu đồ Doanh Thu Năm Nay</h2>
        </div>
        <div className="w-full h-80">
          <ResponsiveContainer>
            <BarChart
              data={data.monthlyRevenue}
              margin={{ top: 10, right: 10, left: 10, bottom: 5 }}
            >
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f0f0" />
              <XAxis
                dataKey="month"
                tickFormatter={(m) => `T${m}`}
                axisLine={false}
                tickLine={false}
                tick={{ fontSize: 12, fill: '#9ca3af' }}
              />
              <YAxis
                axisLine={false}
                tickLine={false}
                tickFormatter={(val) => `${(val / 1000000).toFixed(0)}M`}
                tick={{ fontSize: 12, fill: '#9ca3af' }}
              />
              <Tooltip
                formatter={(value) => [formatVND(value), 'Doanh thu']}
                labelFormatter={(label) => `Tháng ${label}`}
                contentStyle={{ borderRadius: '12px', border: '1px solid #e5e7eb', boxShadow: '0 4px 16px rgba(0,0,0,0.08)' }}
                cursor={{ fill: '#f9fafb' }}
              />
              <Bar
                dataKey="revenue"
                fill="#1a1a1a"
                radius={[6, 6, 0, 0]}
                maxBarSize={48}
              />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
}
